using System;

namespace StdbModule;

public static partial class FrenchQuotes
{
    public static class FrançoisRabelais
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Mieulx est de ris que de larmes escripre, pour ce que rire est le propre de l'homme.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Ne vîtes vous jamais un chien rencontrant quelque os médullaire ? C'est comme dit Platon Livre II de Rép. la bête du monde la plus philosophe. Si vous l'avez vu : vous avez pu noter avec quelle dévotion il le guette, quel soin il le garde, quelle ferveur il le tient, quelle prudence il l'entame, quelle passion il le brise, quelle diligence il le suce. Qu'est-ce qui le conduit ainsi ? Quel est l'espoir de ses recherches ? quel bien prétend-il ? Rien de plus qu'un peu de moelle.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "De même, il vous convient d'être sage pour flairer, sentir, et estimer ces beaux livres de grande valeur, faciles à l'approche, hardis à l'attaque. Puis par lecture attentive, et méditation fréquente, rompre l'os et sucer la substantifique moelle.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Alors les flacons circulèrent, les jambons trottèrent, les gobelets volèrent, les vases de tinter. « Débouche, donne, tourne, brouille. (...) Lequel fut le premier de soif ou de beuverie ? Soif. Car qui eut bu dans le temps de l'innocence ? Beuverie. Car la privation suppose l'habitude. (...) Je mouille, j'humecte, je bois. Et tout de peur de mourir. Buvez toujours, vous ne mourez jamais. (...) Le grand dieu fit les planètes : et nous faisons les plats nez. J'ai la parole de Dieu en bouche : ''Je bois''. (...) O lacryma Christi : c'est de la Devenière, c'est vin pineau.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Gargantua, de trois jours jusqu'à cinq ans fut élevé et instruit conformément à la discipline commandée par son père, et il passa ce temps comme les petits enfants du pays, à savoir boire, manger et dormir ; à manger, dormir et boire ; à dormir, boire et manger.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Mais pour conclure, je dis et je maintiens qu'il n'y a rien de tel comme torchecul qu'un oisillon bien duveteux, pourvu qu'on lui tienne bien la tête entre les jambes. Et croyez-moi sur mon honneur. Car vous sentez au trou du cul une volupté mirifique, tant par la douceur du duvet, que par la chaleur tempérée de l'oisillon, laquelle est facilement communiquée au rectum et autres intestins, jusqu'à venir à la région du cœur et du cerveau.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Car le peuple de Paris est si sot, si badaud et si inepte de nature qu'un bateleur, un porteur de requêtes, un mulet muni de grelots, un joueur de vielle au milieu d'un carrefour assemblera plus de gens que ne fera un bon prêcheur évangélique. Et si importunément le poursuivirent qu'il fut contraint de se réfugier sur les tours de Notre-Dame. (...) Alors en souriant détacha sa belle braguette, et tirant sa mentule en l'air les compissa si aigrement, qu'il en noya deux-cent-soixante-mille-quatre-cent-dix-huit.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Quand Ponocrates connut la manière vicieuse dont Gargantua vivait, il décida de changer son étude des lettres, mais la toléra pour les premiers jours, considérant que la nature n'endure des mutations soudaines sans grande violence.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Il n'y a rien de si vrai que le froc et la cagoule attirent les opprobres, injures et médisances du monde, comme le vent Cecias attire les nuées. La raison péremptoire vient du fait qu'ils mâchent la merde du monde, c'est-à-dire les péchés, et on les éloigne dans leurs retraites comme des machemerdes : les couvents et les abbayes, séparées des conversations politiques comme les commodités d'une maison.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Le temps n'est plus de conquérir les royaumes en détruisant son prochain, son frère chrétien, cette imitation des anciens Hercule, Alexandre, Hannibal, Scipion, César et semblables : agir comme tel est contraire à l'enseignement de l'évangile par lequel nous est commandé par, garder, sauver, régir et administrer chacun ses pays et terres, non envahir les autres avec hostilité. Ce que les Sarrasins et les Barbares appelèrent jadis prouesses, maintenant nous l'appelons pillages et malfaisance.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Toute leur vie était régie non par des lois, des statuts ou des règles, mais selon leur volonté et leur libre arbitre. Ils sortaient du lit quand bon leur semblait, buvaient, mangeaient, travaillaient, dormaient quand le désir leur en venait. Nul ne les éveillait, nul ne les obligeait à boire ni à manger, ni à faire quoi que ce soit. Ainsi en avait décidé Gargantua. Et toute leur règle tenait en cette clause : ''Fais ce que tu voudras.'' Parce que les gens libres, bien nés, bien éduqués, vivant en bonne société, ont naturellement un instinct, un aiguillon qu'ils appellent honneur et qui les pousse toujours à agir vertueusement et les éloigne du vice.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Attendez un peu que je respire quelque trait de cette bouteille : c'est mon vrai et seul Hélicon, c'est ma fontaine chevaline, c'est mon unique inspiration. En buvant, je réfléchis, je discours, je résouds et conclus. Après l'épilogue, je ris, j'écris, je compose, je bois. Ennius buvant écrivait, écrivant buvait. Eschyle (si vous en croyez les ''Symposiaques'' de Plutarque) buvait composant, composant buvait. Homère n'écrivit jamais à jeun. Caton n'écrivait qu'après avoir bu. Ne me dites donc pas que je vis sans suivre l'exemple des biens loués et des plus estimés.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Notez ici, Buveurs, que la manière d'entretenir et de conserver un pays nouvellement conquis n'est pas (contrairement à l'opinion de certains esprits tyranniques, à leur dam et déshonneur) de piller, forcer, guerroyer, ruiner et d'humilier les peuples et de les gouverner avec des verges de fer ; bref, les peuples mangeant et dévorant, de même qu'Homère appelle le roi inique Démovore, c'est-à-dire mangeur de peuple.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Imaginez au contraire un monde autre, dans lequel chacun prête, chacun doit, tous étant endettés, tous étant créanciers.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Je ne bâtis que pierres vives, ce sont hommes.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Chacun abonde en son sens, même pour des affaires étrangères, externes et indifférentes, lesquelles ne sont ni bonnes ni mauvaises, puisqu'elles ne viennent ni de nos cœurs et de nos pensées, siège de tout bien et de tout mal : bien, si l'esprit pur et bon règle la passion ; mal, si la passion est dépravée hors de la justice par volonté diabolique.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Car les bons pères de religion, suivant une règle cabalistique non écrite, mais transmise de génération en génération, en se levant, de mon temps, pour les mâtines, faisaient certains préparatifs remarquables avant d'entre dans l'église. Fiantaient aux fiantoirs, pissaient aux pissoirs, crachaient aux crachoirs, toussaient aux toussoirs mélodieusement, révaient aux révoirs, afin de rien de ne rien porter d'immonde au service divin. Ces choses faites, il se dirigeaient dévotement vers la sainte chapelle(ainsi était nommé en leur palais la cuisine claustrale) et dévotement sollicitaient qu'un bœuf fut mis au feu pour le déjeuner des religieux de Notre Seigneur.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Voulez-vous connaitre davantage la vérité par pyromancie, par aéromancie, célébrée par Aristophane dans ses Nuées, par hydromancie, par lecanotmancie, célébrée au plus au point jadis par les Assyriens, et éprouvée par Ermolao Barbaro ? Dans un bassein plein d'eau je te montrerai ta femme future, forniquant avec deux rustres.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Je crains qu'à la suite d'une longue absence en compagnie de notre roi Pantagruel, où il ira voir à tous les diables, ma femme me fera cocu. Voici la conclusion péremptoire : car tous ceux à qui j'en ai parlé me le font craindre et affirment que c'est une prédestination céleste.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Quand je dis femme, je dis un sexe si fragile, si variable, si changeant, si inconstant et imparfait, que la nature me semble (parlant en tout honneur et révérence) s'être égaré du bon sens par lequel elle avait créé et formé toute chose, quand elle a inventé la femme ; et, y ayant pensé cent cinq fois, ne sais à quoi m'en résoudre sinon que, forgeant la femme, elle a eu égard à la délectation sociale de l'homme et à la perpétuation de l'espèce humaine, beaucoup plus qu'à la perfection de la particularité féminine.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Le nom de Pantagruelion vient également de ses vertus et des ses singularités ; car, de même que Pantagruel fut l'idée et l'exemple de toute joyeuse perfection (je crois que personne d'entre vous, buveurs, n'en doute), de même je reconnais dans le Pantagruélion tant de vertus, tant d'énergie, tant de perfection, tant d'effets admirables, que, si elle sis qualités étaient connues lorsque les arbres (selon la relation du Prophète) firent élection d'un roi de bois pour les régir et les dominer, elle aurait sans doute emporté la majorité des voix et des suffrages.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Mais la calomnie de certains cannibales, misanthropes, agelastes, avait était si atroce et déraisonnée à mon encontre, qu'elle avait vaincu ma patience ; et je ne désiré plus écrire un iota. Car l'une de leurs moindre injures était que de tels livres étaient farcis d'hérésies diverses : ils ne pouvaient toutefois en dévoiler aucune et nulle part, beaucoup de folatries joyeuses sans offense de Dieu et du Roi (c'est l'unique thème et sujet de ces livres) mais non d'hérésies, sauf à interpréter de travers, contre tout usage de la raison et de la langue commune, interprétations pour lesquelles j'aurais préféré mille fois mourir plutôt que de les avoir pensé, si cela était possible : lisait pierre à la place de pain, le serpent pour le poisson, le scorpion pour l'œuf.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Soudain, je ne sais comment cela est arrivé, je n'eus le temps de l'observer, Panurge, sans rien ajouter, jette son mouton, criant et bêlant, dans la mer. Tous les autres moutons criant et bêlant d'une même intonation commencèrent à se jeter et sauter dans la mère successivement. Le troupeau se disputait la première place pour sauter après leur compagnon. Impossible de les en empêcher. Comme vous savez être dans la nature du mouton de suivre le premier, quelque part, où qu'il aille. Ainsi Aristote, dans Histoire des animaux, ''liv. 9'', le dit être le plus sot et inepte être animé du monde.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Quand un moine, prêtre, usurier ou avocat veut du mal à quelque gentilhomme de son pays, il lui envoie un Chicanous. Le Chicanous l'interpellera, l'assignera, l'outragera, l'injurira sans pudeur, suivant son rapport et ses instructions, si bien que le gentilhomme, s'il n'est paralytique de sens, ni plus insensible qu'un têtard, sera contraint lui donner des bastonnades, des coups d'épées sur la tête, ou sur les jarrets, ou mieux le jeter par les créneaux et fenêtres de son château. Cela fait, voilà Chicanous riche pour quatre mois. Comme si les coups de bâtons étaient ses moissons naturelles. Car il aura du moine, de l'usurier oou de l'avocat un salaire conséquent, avec la réparation du gentilhomme, si grande et excessive qu'il y perdra tout son avoir, avec le danger de pourrir mérisablement en prison, comme s'il avait frappé le roi.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "O qu'is sont trois et quatre fois heureux ceux qui plantent des choux ! O Parques, pourquoi ne m'avoir pas tissé une vie de planteur de choux ? O qu'il est petit le nombre de ceux à qui Jupiter accorda une telle ferveur, être destiné à planter des choux. Car ils ont toujours un pied à terre, l'autre n'est jamais loin. Débat de la félicité et du souverain bien qui voudra, mais quiconque plante choux est à présent par mon décret déclaré bienheureux, et ce avec la raison suprême que Pyrrhon, étant dans un danger pareil au nôtre, et voyant un pourceau près du rivage qui mangeait de l'orge répandu, le déclara bien heureux pour deux motfis, à savoir son orge à foison, et plus encore le fait qu'il sur terre ferme. Ah, pour manoir déifique et seigneurial, il n'est que le plancher des vaches.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Le nom de vos deux colonels, Riflandouille et Tailleboudin, dit Epistémon à Pantagruel, nous promet de l'audace, de la chance et la victoire, si par hasard ces Andouilles voulaient nous outrager.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "En voyant le désarroi et le tumulte, Frère Jean ouvre les portes de sa Truie, et sort avec ses bons soldats, les uns portant broches de fer, les autres tenant landiers, chenets, poêlles, pelles, chaudrons, grilles, fourgons, tenailles, lèchefrites, balais, marmites, mortiers, pilons, tous en ordre comme des brûleurs de maison : hurlant et criant épouvantablement.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Mais en cette vie mortelle, rien n'est heureux de toute part. Souvent, quand nous sommes à tables, nous alimentant de quelque bon et grand vent de Dieu, comme une manne céleste, aises comme des seigneurs, quelque petite pluie survient, laquelle nous l'enlève et l'abat. Ainsi sont maints repas perdus par fautre de victuailles.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Alors que le calme et la paix régnait dans tout l'empire chrétien, eux seuls se livrent à des guerres félonnes et très cruelles.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "C'est (dit Homenaz) toujours contre les rebelles, les hérétiques, le sprotestants désespérés désobéissant à la sainteté de ce bon Dieu en terre. Cela lui est non seulement permis et licite : et doit mettre à feu et à sang Empereurs, Rois, Ducs, Princes, Républiques, s'ils transgressent d'un ioda de ses prérogatives : les spolier de leurs biens, les déposséder de leurs royaumes, les proscrire, les réprouver, occire leurs proches et leurs enfants, également damner leurs âmes au plus profond de la plus ardente chaudière de l'Enfer.", Author = "François Rabelais" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/François_Rabelais", Text = "Alors il nous jeta sur le tillac de pleines poignées de paroles gelées, et qui semblaient être des dragées perlées de diverses couleurs. Nous y", Author = "François Rabelais" },
        };
    }
}